// Teaching/refresher notes for Saxon 7/6 — built for JACOB's own understanding and
// teaching prep, same motivation as latin-teacher-guide.ts (Jacob, 2026-09-09: "did u
// use those resources to give me better learning and teaching and personal growth in
// those areas, particularly latin?" — this is the Saxon half of that answer).
//
// IMPORTANT SOURCING NOTE — different from latin-teacher-guide.ts: the photographed
// Saxon material (~/Desktop/MT;RCAmaterial) was ONLY the book's table of contents and
// front matter, not a teacher's-guide-with-scripts the way First Form Latin's Teacher
// Guide was. So this file does NOT claim to transcribe or paraphrase any real Saxon
// pedagogy — it's original explanations of the underlying math concepts (standard,
// widely-taught material, same "nobody owns how cross-multiplication works" status as
// latin-core.ts's standard grammar facts) plus common, well-established student
// mistakes for each concept, written to help Jacob refresh his own understanding
// before teaching it. Deliberately NOT exhaustive across all 120 lessons — skips the
// straightforward arithmetic/review lessons an adult doesn't need a refresher on, and
// covers only the topics genuinely worth a personal refresher (geometry formulas,
// proportions/ratios, exponents, probability, algebra, etc.). Cross-referenced against
// saxon-76.ts's own lesson-topic annotations for which lesson numbers actually exist
// and what they're really called.

export type SaxonTeacherNote = {
  /** Lesson number, or e.g. "Investigation 6" for investigations. */
  key: string;
  title: string;
  concept: string;
  watchFor: string;
  /** RTI/MTSS Tier 1–3 differentiation strategies grounded in K-12 intervention research,
   * adapted to this lesson's specific content. Tier 1 = whole-class fluency/practice;
   * Tier 2 = small-group concrete manipulatives/reteach; Tier 3 = intensive daily with
   * diagnostic assessment and intervention adaptation. Optional — only present if
   * differentiation applies. Sourced from Tony's estate (Rick RIB pass, 2026-08-11). */
  differentiation?: {
    tier1?: string;
    tier2?: string;
    tier3?: string;
  };
};

export const saxonTeacherGuide: SaxonTeacherNote[] = [
  { key: "19", title: "Factors, Prime Numbers", concept: "A factor of a number divides it evenly with no remainder. A prime number has exactly two factors (1 and itself) — 1 is NOT prime (it only has one factor), and 2 is the only even prime.", watchFor: "Students often forget to check both 1 and the number itself when listing factors, or mistakenly call 1 prime.", differentiation: { tier1: "Model live: say 'I'm looking for all factors of 12. Let me check: 1? Yes, 12÷1=12. 2? Yes, 12÷2=6. 3? Yes, 12÷3=4. 4? Yes. 5? No. 6? Yes.' List them: 1, 2, 3, 4, 6, 12. Say: 'I always check 1 and the number itself first.' Have students list factors of 6, 15, 20 while saying the check aloud for each.", tier2: "Small-group: provide number cards and a factor-finding template. For each number, have students list divisors by trial (1, 2, 3... up to the number). Circle 1 and the number itself as automatic factors. Use small numbers (6–20) first. Check: 'How many factors does a prime have?' (two: 1 and itself).", tier3: "Diagnostic: ask 'What are all the factors of 12?' If they miss any, ask 'Did you check 1?' and 'Did you check the number itself (12)?' Teach the divisibility check: 'Is 12÷3 a whole number? Yes, so both 3 and 4 are factors.' Daily factor drills on 5 numbers, emphasizing 1 and the original number are never skipped." } },
  { key: "20", title: "Greatest Common Factor (GCF)", concept: "The GCF of two numbers is the largest number that divides both evenly — found by listing factors of each and picking the largest shared one, or by comparing prime factorizations.", watchFor: "Students confuse GCF with LCM (Lesson 30) — GCF is always ≤ both numbers, LCM is always ≥ both numbers; that size check alone catches most mix-ups.", differentiation: { tier1: "Model on the board: 'Factors of 12: 1, 2, 3, 4, 6, 12. Factors of 18: 1, 2, 3, 6, 9, 18.' Draw boxes around the common ones: 1, 2, 3, 6. Circle the largest: 6. Say: 'GCF of 12 and 18 is 6. Is 6 ≤ both 12 and 18? Yes. GCF is never bigger than either number.' Do 2 more examples (pairs like 8 & 12, 15 & 25) with the class saying the common factors.", tier2: "Small-group: give pairs of numbers (12 & 18, 8 & 20, 15 & 30). Have students list factors of each on two lines, circle the common ones, then box the largest. Use a size-check: 'Is this GCF smaller than both numbers? Yes — that's how we know.' Daily practice on 3–5 pairs.", tier3: "Diagnostic: ask 'What's the GCF of 12 and 18?' If they answer 36 (confusing with LCM), ask 'Is 36 smaller than both 12 and 18? No — GCF must be ≤ both numbers.' List factors together: 'What do 12 and 18 both divide evenly into? 1, 2, 3, 6. Largest shared? 6.' Spaced drills 3x weekly." } },
  { key: "Investigation 2", title: "Investigating Fractions with Manipulatives", concept: "Hands-on fraction bars/circles building physical intuition for equivalent fractions and comparing fraction size before the abstract common-denominator rules take over. (Research: manipulatives show small-to-moderate overall effects, with strongest gains on retention; benefits require THREE conditions: long-term use over weeks/months, explicit linking between the physical model and the symbolic representation, and gradual fade from concrete to pictorial to abstract, not concrete-only.)", watchFor: "Don't skip the physical modeling even if it feels slow — students who never build this intuition tend to make sign/size errors on fraction comparison later that pure algorithm practice doesn't fix. Avoid flashy multicolored manipulatives; plain fraction bars are more effective. Always name the symbols aloud while touching the model (e.g., this bar is 1/4, so four of these bars make the whole 1) so the symbol-linking is explicit.", differentiation: { tier1: "Model live with fraction bars: hold up a 1/4 bar, name it aloud, then count four into a whole. Have students repeat while handling their own bars. Frequent opportunities to respond: 'Show me a 1/3 bar,' 'How many thirds in a whole?'", tier2: "Small-group: students build fractions you name, then write the symbolic form. Bridge concrete→pictorial by drawing the bars on paper and labeling. Work with halves/fourths/eighths (most intuitive) before thirds/sixths.", tier3: "Diagnostic: ask 'Show me 2/4 with the bars. Is that the same as 1/2?' Listen for the reasoning. If they can build but can't see equivalence, overlay the 2/4 bar on the 1/2 bar. Weekly bar-based comparisons until prediction without bars." } },
  { key: "23", title: "Ratio", concept: "A ratio compares two quantities (3:4, or 3/4) — order matters, and a ratio is NOT the same as a fraction of a whole unless the two quantities are literally part and whole.", watchFor: "Students flip ratio order (writing 4:3 for '3 cats to 4 dogs') — always ask 'which number came first in the sentence.'" },
  { key: "27", title: "Measures of a Circle", concept: "Radius, diameter (2× radius), and circumference are the three measurements to keep straight before Pi is introduced formally at Lesson 47.", watchFor: "Students mix up radius and diameter constantly — a quick \"radius reaches the center, diameter crosses all the way through\" phrase helps." },
  { key: "Investigation 3", title: "Measuring and Drawing Angles with a Protractor", concept: "Physical protractor skills: aligning the base line, reading the correct scale (inner vs. outer numbers), and estimating before measuring to catch a wrong-scale reading.", watchFor: "The single most common protractor error is reading the wrong number scale (e.g. reading 120° as 60°) — teach \"estimate first\" as the built-in error check." },
  { key: "30", title: "Least Common Multiple (LCM), Reciprocals", concept: "LCM is the smallest number that's a multiple of both given numbers (used to find common denominators). A reciprocal flips a fraction (3/4 → 4/3); multiplying a number by its reciprocal always gives 1.", watchFor: "Students find A common multiple instead of the LEAST one (e.g. using 24 as the LCM of 4 and 6 instead of 12) — remind them to check if a smaller shared multiple exists.", differentiation: { tier1: "Model list-making on the board: multiples of 4 (4, 8, 12, 16, 20, 24...), multiples of 6 (6, 12, 18, 24...). Circle the shared ones, box the smallest. Say aloud: 'Common multiple = appears in both lists. LEAST common = the smallest one.' Have students list multiples for 2–3 pairs with you watching, then check their 'least' claim by asking 'Is there a smaller one?'", tier2: "Small-group: give students a template with two rows (multiples of 4, multiples of 6) and have them fill in at least 10 multiples, then circle the common ones and box the LCM. Use pairs where LCM is small (4 & 6, 3 & 5, 2 & 8). For reciprocals, use index cards: write 3/4, and have them write the reciprocal (4/3), then multiply to check (= 12/12 = 1).", tier3: "Diagnostic: ask 'What's the LCM of 4 and 6?' If they answer 24, ask 'Is 24 a common multiple?' (yes) 'Is it the LEAST one?' Recount the multiples with them until they find 12. For reciprocals, if they can't identify the flip or can't verify it multiplies to 1, use a manipulative: 'You have 3/4 of a pizza. The reciprocal asks: how many 3/4 slices make one whole?' (answer = 4/3). Spaced drills on LCM 3–4 times weekly." } },
  { key: "33", title: "Writing Percents as Fractions, Part 1", concept: "Percent literally means \"per hundred\" — 45% = 45/100, which then simplifies like any fraction.", watchFor: "Students forget to simplify after converting, or misplace the decimal point when going percent → decimal → fraction.", differentiation: { tier1: "Use a 10×10 grid visual on the board: shade 45 squares, say 'Forty-five out of one hundred = 45/100 = 45%.' Have students shade grids for 30%, 50%, 75% while saying the fraction aloud. Always follow with simplification: '45/100: both divisible by 5 = 9/20.' Model two full examples before assigning grid work.", tier2: "Small-group: provide grids + fraction cards (45/100, 9/20, 45%). Have them match the grid to the fraction and percent, then simplify one at a time. Use 'friendly' percentages (25%, 50%, 75%, 20%, 10%) before introducing others. Always require simplification; use a GCF reminder card if needed.", tier3: "Diagnostic: give them 'Convert 45% to a fraction.' If they write 45/100 and stop, say 'Can we simplify this?' Teach the 'GCF-and-divide' process: find GCF of 45 and 100, divide both. If they can't find GCF, drill GCF for 45 & 100 separately. Daily percent→fraction conversions (5–10) with emphasis on simplification as a required step." } },
  { key: "38", title: "Squares and Square Roots", concept: "Squaring a number multiplies it by itself; square root asks \"what number times itself gives this?\" They're inverse operations, and most square roots (beyond perfect squares like 4, 9, 16, 25) aren't whole numbers.", watchFor: "Students confuse √9 (=3) with 9² (=81) purely from mixing up which direction the operation goes — anchor it with \"root undoes square.\"", differentiation: { tier1: "Model with a table on the board: write numbers 1–5 down the left, squares (1, 4, 9, 16, 25) on the right. Say: '3² means 3 times 3 = 9. √9 asks: what number times itself gives 9? Answer: 3. Root UNDOES square.' Do 2–3 more pairs (5² and √25, 2² and √4). Say the relationship aloud each time: 'square goes up, root comes back down.'", tier2: "Small-group: give cards with numbers and their perfect squares (3↔9, 5↔25, 4↔16). Have students match them and say: '3 squared is 9, square root of 9 is 3.' Create a two-way arrow to show the inverse. Use only perfect squares for now. Daily matching drills on pairs 1–10.", tier3: "Diagnostic: ask '3² = ?' and '√9 = ?' separately. If they confuse them, use the arrow/undoes language: 'Squaring goes one direction: 3→9. Root goes the opposite: 9→3. They undo each other.' Spaced daily practice on the 10 main perfect squares (1–100) and their roots." } },
  { key: "47", title: "Circumference, Pi", concept: "Pi (≈3.14) is the fixed ratio of any circle's circumference to its diameter — circumference = π × diameter (or 2πr). It's the same for every circle regardless of size, which is the actually surprising fact worth stating explicitly.", watchFor: "Students plug the radius into the diameter formula (or vice versa) — always confirm which one a given problem provides before applying C = πd.", differentiation: { tier1: "(R5 technique: establish the ONE focus upfront — 'today we're confirming whether we have radius or diameter before applying any formula.') Draw a circle on the board: mark the center, draw radius (center to edge), label 'r'. Draw diameter (all the way across), label 'd = 2r'. Say: 'Circumference = π × diameter, which is πd or π(2r).' Give 3–4 problems, each with a circle showing ONLY the radius or ONLY the diameter labeled. Have students identify which it is BEFORE applying the formula.", tier2: "Small-group: provide circles with either the radius or diameter marked. For each: (1) identify which measurement you have, (2) convert to the other if needed (if r given, d = 2r), (3) apply C = πd. Start with problems that provide the diameter directly, then add problems where they must convert from radius.", tier3: "Diagnostic: show a circle with radius 3 cm marked. Ask 'What's the circumference?' Watch: do they use C = π(3) or C = π(6)? If they use r directly, ask 'Is that the radius or the diameter?' Reteach: 'diameter = 2 times the radius, so d = 6. Then C = π × 6.' Daily practice on 3–5 circles, checking the identification step aloud before computing." } },
  { key: "Investigation 6", title: "Attributes of Geometric Solids", concept: "Faces (flat surfaces), edges (where two faces meet), and vertices (corners) — Euler's formula (faces + vertices − edges = 2) holds for any convex solid, a nice \"why does this always work\" moment if students notice the pattern.", watchFor: "Students miscount hidden faces/edges/vertices on a 3D drawing — physical models (or even a real box) beat a flat sketch for this lesson." },
  { key: "58", title: "Probability and Chance", concept: "Probability = favorable outcomes / total possible outcomes, always between 0 (impossible) and 1 (certain), often expressed as a fraction, decimal, or percent.", watchFor: "Students think a fair coin \"owes\" them a result after a streak (the gambler's fallacy) — each flip is independent regardless of prior flips, worth addressing directly since it's a genuinely common misconception, not just a careless error.", differentiation: { tier1: "Flip a coin or spin a spinner in front of the class 5–6 times. If you get heads 4 times, say: 'Some people think the next flip is \"due\" to be tails. But the coin has NO memory. The probability of heads is STILL 1/2 on the next flip.' Do 3 more flips and count: record the results but emphasize 'each flip is independent.' Say: 'What happened before doesn't change what happens next.' Do a real probability calculation: 'Out of 20 flips, we got 13 heads and 7 tails. Is the coin broken? No — coin flips have randomness.'", tier2: "Small-group: give students a coin or spinner. Have them conduct 10 trials and tally results. Then ask: 'If we did 10 MORE, do you expect heads to catch up to make it even?' Answer: not necessarily. Do those 10 more trials. Compare both sets. Discuss: 'Did the coin \"remember\" the first 10?' (No. Each set is independent.) Use the language: 'Each trial has no memory of the last one.'", tier3: "Diagnostic: ask 'A coin shows heads 5 times in a row. Is tails more likely on the next flip?' If yes, correct: 'No. The coin has no memory. P(heads) = 1/2 always. Tails isn't \"due.\"' Run 20 real flips together and record. Show: long streaks *will* happen by chance. Teach: independence = each outcome has the same probability regardless of history. Daily coin/spinner trials (10–20) with emphasis on independence." } },
  { key: "60", title: "Polygons", concept: "A polygon is any closed shape made of straight line segments; \"regular\" means all sides and angles are equal. Naming follows side count (pentagon=5, hexagon=6, octagon=8, etc.).", watchFor: "Students assume any 5-sided shape is automatically \"regular\" — regularity is about equal sides AND angles, not just the side count." },
  { key: "64", title: "Classifying Quadrilaterals", concept: "The quadrilateral family tree matters: a square is a rectangle (all angles 90°) AND a rhombus (all sides equal); a rectangle and rhombus are both parallelograms; not every parallelogram is a rectangle or rhombus.", watchFor: "Students treat these as separate, unrelated categories instead of a nested hierarchy — a Venn diagram on the board fixes this faster than a definition list.", differentiation: { tier1: "Draw a Venn diagram live on the board with three overlapping circles: Parallelograms (outer), Rectangles (left circle), Rhombuses (right circle), Square (center overlap). Place quadrilateral names in their correct regions. Say: 'A square is BOTH a rectangle AND a rhombus because it has 90° angles AND equal sides.' Point to a rectangle: 'This is a parallelogram but NOT a rhombus (unequal sides).' Do this multiple times with students placing new quadrilaterals on the diagram.", tier2: "Small-group: provide a blank Venn diagram and a set of quadrilateral cards (square, rectangle, rhombus, parallelogram, trapezoid). Have students sort them into the right region, justifying each placement: 'Why is a square in the center overlap?' (has both properties). Use the language: 'A ___ is a special kind of ___.'", tier3: "Diagnostic: ask 'Is every rectangle a parallelogram?' If no, ask 'Does a rectangle have two pairs of parallel sides? Yes. So it's in the parallelogram family.' Use a specific shape: 'Is a rhombus a square?' Answer: only if it also has right angles. Draw examples. Daily classification practice with shapes they place on a Venn diagram." } },
  { key: "65", title: "Prime Factorization, Division by Primes, Factor Trees", concept: "Every whole number > 1 breaks down into a unique product of prime numbers (the Fundamental Theorem of Arithmetic) — a factor tree is just a visual way to find that breakdown by repeatedly dividing by primes.", watchFor: "Students stop a factor tree branch too early on a composite number (e.g. leaving 4 as a \"final\" branch instead of continuing to 2×2) — the rule is: keep splitting until every branch ends in a prime.", differentiation: { tier1: "Draw a factor tree for 24 on the board. Start at the top: 24. Split into 6 × 4. Circle 6 (composite, keep splitting): 2 × 3. Circle 4 (composite, keep splitting): 2 × 2. Now all bottom boxes are primes: 2, 3, 2, 2. Say aloud: 'Every branch must end in a prime. If it's not prime, keep splitting.' Do 12 and 30 the same way. Have students say 'Is that prime?' for each box before moving on.", tier2: "Small-group: give factor-tree templates with numbers like 12, 18, 20. Have students fill in the splits step by step. Rule: 'If a box is composite (not prime), draw branches below it.' Check each step: 'Is 6 prime? No, so split it.' Use a 'prime checklist' — factors of 2, 3, 5 are primes; anything else, check divisibility.", tier3: "Diagnostic: show a partial factor tree for 24 with 4 left as a final box. Ask: 'Is this done?' If yes, ask 'Is 4 prime?' (No.) 'Then what?' (Split it into 2 × 2.) Teach: 'Every leaf of the tree must be prime — no composite numbers allowed at the bottom.' Daily practice on 10 numbers with emphasis on 'Is that prime?' at each step." } },
  { key: "69", title: "Complementary and Supplementary Angles", concept: "Complementary angles sum to 90°; supplementary angles sum to 180°. (\"C comes before S in the alphabet, 90 comes before 180\" is a real memory hook if a mnemonic helps.)", watchFor: "Students swap the two definitions constantly — tie \"complementary\" to a right angle (90°, like the corner of a square) and \"supplementary\" to a straight line (180°) as visual anchors.", differentiation: { tier1: "Draw two visuals on the board: (1) a RIGHT ANGLE (corner of a square, 90°) labeled 'Complementary = Complete a right angle.' (2) A STRAIGHT LINE (180°) labeled 'Supplementary = Straight line.' Say: 'Complementary + complementary = 90° (complete a right angle). Supplementary + supplementary = 180° (make a straight line).' Give 3–4 example pairs (30° and 60° are complementary; 45° and 135° are supplementary) and have students identify which visual each matches.", tier2: "Small-group: provide angle pairs and two posters (right angle and straight line). For each pair, students determine the sum and match it to the correct visual. Use pairs where one is complementary and one supplementary side by side so they contrast: 'These add to 90 (complementary), these add to 180 (supplementary).' Daily practice on 5–6 pairs.", tier3: "Diagnostic: ask 'If an angle is 35°, what's its complementary angle?' If wrong, ask 'Complementary angles add to what? 90. So 90 − 35 = ?' Then ask: 'If an angle is 35°, what's its supplementary angle?' (180 − 35 = 145.) Teach the subtraction pattern: comp = 90 − angle, supp = 180 − angle. Daily drills on 3–5 angles for both types." } },
  { key: "71", title: "Parallelograms", concept: "Opposite sides are parallel AND equal in length; opposite angles are equal; consecutive angles are supplementary (add to 180°). Area = base × height (NOT base × slant side).", watchFor: "The #1 error: using the slanted side length instead of the perpendicular height when calculating area — always confirm which measurement is actually perpendicular to the base. (R5 technique: this is the ONE misconception to pre-empt; use clinically focused feedback rather than addressing all parallelogram properties at once. Establish upfront: 'today we're locking down the height-not-slant rule.)'", differentiation: { tier1: "Draw a parallelogram with a base and a slanted side visibly different. Drop a perpendicular height line from the top, and say 'This perpendicular line is the HEIGHT, not the slant.' Shade the base and the height in different colors. Say aloud: 'Area = base × height (the perpendicular one), NOT base × slant.' Model three examples, each time pointing to the HEIGHT before multiplying. (R5: model-then-release — show the full worked problem first before releasing to practice.)", tier2: "Small-group: provide parallelogram cards with base, slant, and height labeled. Have students write the area formula (base × height) BEFORE calculating, then circle which measurement goes in the height slot. Use consistent language: 'Is the height perpendicular? Yes, so use it.' For each parallelogram, ask 'Would using the slant side be right or wrong?' (wrong, show why).", tier3: "Diagnostic: give them a parallelogram with base, slant, and height provided. Ask 'What's the area?' Watch which number they use for height. If they use the slant, ask 'Is the slant perpendicular to the base?' (no). 'Then what's perpendicular?' (the height). Reteach the 'perpendicular height' concept with physical models (e.g., a tilted ruler is the slant, a vertical line is the height). Daily parallelogram-area problems emphasizing 'Is it perpendicular?' before calculating." } },
  { key: "Investigation 7", title: "The Coordinate Plane", concept: "Ordered pairs (x, y) locate points relative to two perpendicular number lines (axes) meeting at the origin (0,0). The four quadrants each have a distinct sign pattern for (x,y).", watchFor: "Students plot (x,y) backwards, moving up/down first instead of left/right first — \"over then up\" (x before y) as a fixed verbal habit prevents most of these errors." },
  { key: "73", title: "Exponents, Writing Decimal Numbers as Fractions Part 2", concept: "An exponent tells you how many times to multiply the base by itself (2³ = 2×2×2 = 8, NOT 2×3=6) — the most common exponent misconception is treating it as multiplication by the exponent instead of repeated multiplication. (Research: this is the single most-cited exponent error across studies; the mechanism is overgeneralization from prior learning — students apply \"multiply\" to every operator symbol. Explicit correction of this specific error — 'I hear 'two times three,' but the small 3 up there means multiply 2 by ITSELF three times' — prevents persistence of this misconception into high school.)", watchFor: "Explicitly correct \"2³ = 6\" if it comes up — it's an extremely common first-encounter mistake, not a sign of weak math ability. Correct it live, not silently. Use the phrase 'multiply by ITSELF' to distinguish from 'multiply by the exponent.' (R5 technique: establish the ONE focus upfront — 'today we're nailing the difference between 2³ and 2×3' — rather than teaching exponents broadly; narrow feedback prevents cognitive overload.)", differentiation: { tier1: "Model on the board with base-blocks or tallies: write '2³' then expand it: 2 × 2 × 2. Say aloud: 'Two times ITSELF three times, not two times three.' Have students repeat: 'multiply by ITSELF.' Frequent practice: 'What's 3²? Write out 3 × 3,' before evaluating.", tier2: "Small-group: provide a card with the expanded form (2 × 2 × 2) and the answer (8) already visible. Have the student match the written exponent (2³) to the expanded form. Start with 2² and 3², the most intuitive. Daily drills on 2² through 5².", tier3: "Diagnostic: ask 'What's 2³?' If they say 6 or 'two times three,' address it immediately: 'I hear 'two times three,' but the small 3 means multiply by ITSELF. 2³ = 2 × 2 × 2 = 8.' Then drill: 2² = 2 × 2 = 4, then 2³ again. Spaced retrieval 3–4 times weekly; watch specifically for the '2 × 3' error if it reappears." } },
  { key: "80", title: "Using Scale Factor to Solve Ratio Problems", concept: "A scale factor multiplies every dimension of a figure by the same ratio to create a similar (same-shape, different-size) figure — used in maps, models, and blueprints.", watchFor: "Students apply the scale factor to only one dimension (e.g. scaling length but not width) — stress that EVERY linear measurement scales by the same factor, but area scales by the factor SQUARED." },
  { key: "Investigation 8", title: "Geometric Construction of Bisectors", concept: "A perpendicular bisector uses compass-and-straightedge construction (not a protractor) to find the exact midpoint and 90° angle of a segment — an angle bisector splits an angle into two equal halves the same way.", watchFor: "Students want to \"eyeball\" the construction instead of trusting the compass-arc method — the whole point of the lesson is that the geometric method is exact, not estimated." },
  { key: "82", title: "Volume of a Rectangular Prism", concept: "Volume = length × width × height (or base area × height) — measures the 3D space inside a solid, in cubic units.", watchFor: "Students confuse volume's cubic units (in³, cm³) with area's square units — always check the unit label matches the dimension count of the calculation.", differentiation: { tier1: "Draw a 3D rectangular box on the board, label its three dimensions (length, width, height). Say: 'Volume = l × w × h. That's three numbers multiplied, so the answer is in CUBIC units (in³, not in²).' Write the formula and model: 'A box is 5 inches × 3 inches × 2 inches. Volume = 5 × 3 × 2 = 30 cubic inches.' Say: 'Cubic because we multiply THREE dimensions.' Do 2 more examples, each time asking 'How many dimensions? Three. So cubic units.'", tier2: "Small-group: provide rectangular boxes (or draw them) with length, width, height labeled. For each: (1) multiply the three dimensions, (2) write the answer with cubic units (not square). Start with whole-number dimensions. Check: 'Did you use all three sides? Is your unit cubic?' Daily practice on 4–5 boxes.", tier3: "Diagnostic: give a box with dimensions, ask for volume. If they write the answer with square units (in²), ask 'How many dimensions did we multiply? Three. So the unit should be cubic (in³).' Reteach: area = 2D (square units), volume = 3D (cubic units). Practice identifying unit type before computing: 'This asks for volume, so cubic. This asks for area, so square.' Daily practice on mixed area/volume problems." } },
  { key: "83", title: "Proportions", concept: "A proportion states two ratios are equal (a/b = c/d) — the backbone of scale, unit conversion, and percent problems for the rest of the year. This is one of the canonical 'algebra gatekeeper' topics: mastery here predicts success in Algebra I, and the concept of ratio equivalence is where many students get stuck if they rush. (Research: proportional reasoning is a major algebra prerequisite; errors here often track forward to equation-solving mistakes.)", watchFor: "Students set up the ratio with mismatched units on top/bottom (e.g. miles/hours = hours/miles instead of miles/hours = miles/hours) — always label units when setting up the proportion, not just numbers. Spend time on non-computational understanding ('why MUST these two ratios be equal?') before drilling cross-multiplication; the conceptual foundation prevents setup errors later. (R5 technique: establish the pre-agreed focus upfront — 'this lesson focuses on unit alignment; if units don't match across the equal sign, the setup is wrong.' Narrow feedback to this single check rather than trying to teach units AND cross-multiplication AND real-world setup all at once.)", differentiation: { tier1: "Build proportions live on the board with labels: 3 apples / 2 dollars = 6 apples / ? dollars. Point to the structure: 'Top and bottom stay the same units across both sides. 3 goes with 2 on the left, 6 goes with ? on the right.' Model two full examples before practice. Use real objects (coins, counters) if conceptual understanding is shaky.", tier2: "Small-group: give students proportion templates with units labeled: ___ km / ___ hours = ___ km / ___ hours. Have them fill in numbers, then identify 'which ratio should be on top.' Work with 3–4 real-world contexts (maps, recipes, speed) before adding cross-multiplication.", tier3: "Diagnostic: present a proportion setup error (e.g. miles on top and hours on bottom one side, flipped on the other) and ask 'Is this right?' If they can't spot the error, teach the 'label check': write the units under the numbers, make sure they match across the equal sign. Daily label-checking drills on 5–10 proportions; don't move to cross-multiplication until unit-matching is automatic." } },
  { key: "85", title: "Using Cross Products to Solve Proportions", concept: "In a/b = c/d, cross-multiplying gives a×d = b×c — this works because multiplying both sides of the equation by both denominators cancels them out; it's not a magic trick, it's algebra.", watchFor: "Students cross-multiply an expression that ISN'T actually a proportion (e.g. a fraction being added, not set equal to another fraction) — the technique only applies to two fractions set equal to each other.", differentiation: { tier1: "(R5: establish the ONE focus — 'cross-products ONLY work when we have two fractions set equal to each other.') Model on the board: write 3/4 = 6/8. Say: 'Is this a proportion? YES — two fractions with an equal sign. Cross-multiply: 3 × 8 = 4 × 6. Both give 24, so it's true.' Then show a non-proportion: 3/4 + 1/2. Say: 'This is NOT two fractions equal to each other. No cross-multiply here.' Do 3 more: some are proportions (apply cross-multiply), some are not (don't).", tier2: "Small-group: give cards with equations. For each, students first decide: 'Is this a proportion (two fractions = each other)?' Only if yes, cross-multiply. Use cards that clearly show the difference (a/b = c/d vs. a/b + c/d vs. a/b = c/d + e/f). Check the 'is it a proportion?' step before solving.", tier3: "Diagnostic: show 3/5 = 6/10 and ask them to solve. If they cross-multiply, good. Then show 3/5 + 1/2 and ask 'Can we cross-multiply here?' If yes, ask 'Why? Is this two fractions equal to each other?' (No, they're being added.) Teach: cross-multiply only for a/b = c/d form. Daily practice on mixed proportion and non-proportion expressions." } },
  { key: "86", title: "Area of a Circle", concept: "Area = πr² — note it's the RADIUS squared, not the diameter, which is the most common formula mix-up in this lesson.", watchFor: "Students plug the diameter into r² directly — always confirm radius vs. diameter before squaring, same trap as Lesson 47's circumference formula.", differentiation: { tier1: "Draw a circle with radius labeled from center to edge. Say: 'Area = πr². The r must be the RADIUS.' Show a problem: 'If the radius is 5, Area = π × 5² = 25π.' Then give a problem with diameter: 'If the DIAMETER is 10, what's the radius? Half of 10 = 5. Now Area = π × 5² = 25π.' Emphasize: 'Always check: do I have radius or diameter? Adjust if I have diameter.'", tier2: "Small-group: provide circles with EITHER radius or diameter marked. For each: (1) Identify what you have (radius or diameter), (2) If you have diameter, convert to radius (÷2), (3) Apply A = πr². Use clear labeling to prevent confusion. Start with problems that give radius directly.", tier3: "Diagnostic: show a circle with diameter 10 cm. Ask 'What's the area?' If they compute π(10²), ask 'Did we use radius or diameter?' (diameter) 'What's the radius?' (5) 'So area = π × 5² = 25π.' Teach the conversion reflex: always convert diameter → radius before squaring. Daily practice on 3–5 circles, alternating radius-given and diameter-given." } },
  { key: "89", title: "Estimating Square Roots", concept: "For a non-perfect-square, find the two perfect squares it falls between (√50 is between √49=7 and √64=8, so ≈7.1) — a genuinely useful mental-math skill, not just test prep.", watchFor: "Students guess wildly instead of anchoring to the nearest perfect squares — always name the two bracketing perfect squares first.", differentiation: { tier1: "Write the perfect squares on the board: 1, 4, 9, 16, 25, 36, 49, 64, 81, 100. Model: 'What's √50? First, find the perfect squares it falls between: 49 and 64. So √50 is between √49=7 and √64=8. Closer to which? 50 is closer to 49, so √50 ≈ 7 point-something.' Do 3–4 more (√30, √70, √15) the same way. Say: 'Always bracket first, then estimate between.'", tier2: "Small-group: provide a list of perfect squares 1–100. For each non-perfect number (e.g., 50, 20, 80), have students: (1) Name the two bracketing perfect squares, (2) Name the two square roots, (3) Estimate where the answer falls. Use numbers where the brackets are visible.", tier3: "Diagnostic: ask '√50 = ?' If they guess randomly, teach the bracket method: 'Find 49 and 64. √49=7, √64=8. So √50 is between 7 and 8. How close to 7 vs 8? 50 is closer to 49, so ≈7 point-something.' Spaced drills on 10 non-perfect squares, emphasizing the bracketing step." } },
  { key: "90", title: "Measuring Turns", concept: "A full turn = 360°, half turn = 180°, quarter turn = 90° — connects angle measure to real rotational movement (clock hands, compass directions).", watchFor: "Students confuse clockwise/counterclockwise direction when a problem specifies it — physically miming the turn with a hand often resolves this faster than explaining it verbally." },
  { key: "Investigation 9", title: "Experimental Probability", concept: "Experimental probability (from actually running trials and counting results) can differ from theoretical probability (calculated from possible outcomes) — especially with few trials; they converge as trial count grows (the Law of Large Numbers, informally).", watchFor: "Students expect experimental results to exactly match theoretical predictions every time — a small number of trials SHOULD show variance; that's not an error in the experiment." },
  { key: "91", title: "Geometric Formulas", concept: "A consolidation lesson pulling together area/perimeter/volume formulas learned so far — worth Jacob's own quick self-check that he has all of them (rectangle, triangle, circle, parallelogram, rectangular prism) fluent before teaching a review lesson built entirely around recall.", watchFor: "Since this is a formula-recall lesson, the actual teaching risk is presenting it as \"just memorize a list\" instead of re-deriving a couple formulas live (e.g. triangle area as half a parallelogram) so the formulas feel connected, not arbitrary." },
  { key: "92", title: "Expanded Notation with Exponents; Order of Operations with Exponents; Powers of Fractions", concept: "Order of operations (PEMDAS) places exponents before multiplication/division — a fraction raised to a power applies the exponent to BOTH numerator and denominator: (2/3)² = 4/9, not 2/9 or 4/3. (Research: exponent misconceptions peak here because students are now combining two separate skills — exponent meaning AND fraction rules — in one problem. This is exactly where 'worked-example effect' helps most: show a fully-worked (2/3)² → (2/3)×(2/3) → 4/9 BEFORE having students solve similar problems.)", watchFor: "Students apply the exponent only to the numerator of a fraction — explicitly show (2/3)² as (2/3)×(2/3), not 2²/3. (R5 Jim Knight Impact Cycle 'Learn' stage: model two FULL worked examples before releasing to practice; the combination of exponent + fractions is cognitively demanding, and seeing a clean worked example with every step visible reduces errors significantly. Do not skip the modeling and jump to practice.)", differentiation: { tier1: "(R5: model BEFORE releasing to practice.) Write (2/3)² on the board. Say: 'The exponent 2 applies to the WHOLE fraction, not just the top. (2/3)² means (2/3) × (2/3).' Expand it: '= 2/3 × 2/3 = (2×2)/(3×3) = 4/9.' Write it step-by-step, pointing to each part. Do (1/4)² the same way: '(1/4) × (1/4) = 1/16.' Show a second full example with different fractions. THEN release to guided practice.", tier2: "Small-group: provide 3–4 fraction-exponent problems with the expanded form written out. Example: (2/3)² is given as (2/3) × (2/3) already. Have students multiply and simplify. Start with exponent 2 only. Repeat: exponent applies to top AND bottom.", tier3: "Diagnostic: ask (2/3)². If they write 4/3 or 2/9, ask 'The exponent applies to which part? The whole fraction. So we do (2/3) × (2/3). What's 2×2? 4. What's 3×3? 9. So 4/9.' Drill the expansion: exponent 2 means multiply the fraction by itself. Daily practice on (a/b)², mixing small numerators/denominators." } },
  { key: "96", title: "Functions, Graphing Functions", concept: "A function assigns exactly one output to each input — a table of (x,y) pairs or a rule like y = 2x + 1. Graphing plots those pairs to visualize the relationship.", watchFor: "Students think any table of numbers is automatically a function — the actual test is whether any input maps to MORE than one output (if so, it's not a function).", differentiation: { tier1: "Draw a table on the board: x | y with pairs (1,2), (2,4), (3,6). Say: 'Is this a function? Check each input — does 1 always give the same output? Yes, 2. Does 2 always give the same output? Yes, 4.' Now show a non-function: x | y with (1,2), (1,3), (2,4). Say: 'The input 1 gives TWO different outputs: 2 AND 3. Not a function.' Do 3 more tables, some functions and some not. Test: 'For each x, is there only one y?'", tier2: "Small-group: provide tables (both functions and non-functions) and have students check: 'Is there any input with more than one output?' If yes, it's not a function. Use consistent language: 'Each input has exactly one output, or it's not a function.' Daily practice on 5–6 tables, identifying which are functions.", tier3: "Diagnostic: show a table with x=2 appearing twice with different y values. Ask 'Is this a function?' If yes, teach: 'A function means each input gives ONE output. Here, x=2 gives two different y values. Not a function.' Use the vertical-line test on a graph: if a vertical line crosses the curve twice, it's not a function. Daily practice identifying functions by table and by graph." } },
  { key: "97", title: "Transversals", concept: "A transversal is a line crossing two (often parallel) lines, creating 8 angles with specific relationships: corresponding angles are equal, alternate interior angles are equal, co-interior (same-side interior) angles are supplementary.", watchFor: "Students guess at angle relationships instead of using the parallel-lines-cut-by-a-transversal rules — worth drilling the vocabulary (corresponding/alternate/co-interior) explicitly since the rules are useless without knowing which pair you're looking at.", differentiation: { tier1: "Draw two parallel lines crossed by a transversal on the board. Label the 8 angles created: 1,2,3,4 at the top intersection, 5,6,7,8 at the bottom. Say: 'Corresponding angles are in the SAME spot at each intersection: 1 and 5, 2 and 6, etc. They're EQUAL.' Point to each pair. 'Alternate interior angles are between the parallel lines, on opposite sides: 3 and 6, 4 and 5. Also EQUAL.' Drill the vocabulary by having students identify which angles are corresponding, which alternate interior. Do NOT jump to rules until they can name the angle pairs correctly.", tier2: "Small-group: provide diagrams of a transversal crossing two parallel lines, with angles labeled. Give them angle pairs and have them name the relationship: 'Are these corresponding? Alternate interior? Co-interior?' Use consistent definitions on a reference card. Drill: 'Point to two alternate interior angles.' Once they can name relationships, THEN apply the rules (equal or supplementary).", tier3: "Diagnostic: show angles and ask 'Are these corresponding angles?' If they guess wrong, teach the naming first: 'Corresponding are in the same position at each intersection. Show me another pair of corresponding angles.' Build the vocabulary reflex before applying any rules. Daily practice: 10 angle pairs, identify the relationship before stating whether they're equal/supplementary." } },
  { key: "98", title: "Sum of the Angle Measures of Triangles and Quadrilaterals", concept: "Every triangle's interior angles sum to 180°; every quadrilateral's sum to 360° (provable by splitting any quadrilateral into two triangles).", watchFor: "A great moment to actually show the quadrilateral-splits-into-two-triangles proof live rather than just stating 360° as a fact — it's one of the more satisfying \"why is that true\" moments available at this level.", differentiation: { tier1: "(R5: model the proof live before assigning practice.) Draw a triangle, label angles A, B, C. Say: 'A + B + C = 180°.' (If they accept it, move on; if they question it, show the proof: draw a line parallel to the base through the opposite vertex, show alternate interior angles equal, sum to 180°.) Draw a quadrilateral. Say: 'I can split this into two triangles by drawing a diagonal.' Draw the diagonal. 'Triangle 1: angles sum to 180°. Triangle 2: angles sum to 180°. Total: 360°.' Point to the angles and trace the diagonal. Do this live, physically showing the split.", tier2: "Small-group: provide triangle and quadrilateral diagrams. For each triangle, have students measure or calculate the three angles and verify the sum is 180°. For each quadrilateral, split it with a diagonal and verify: Triangle 1 + Triangle 2 = 360°. Use physical models or drawings where angles can be marked.", tier3: "Diagnostic: ask 'Why do triangle angles sum to 180?' and 'Why do quadrilateral angles sum to 360?' If they answer 'because I memorized it,' teach the proof: draw a parallel line (triangle proof) or split with a diagonal (quadrilateral proof). Once they see WHY, it sticks better than memorization. Spaced practice: mix finding missing angles in triangles/quadrilaterals." } },
  { key: "100", title: "Algebraic Addition of Integers", concept: "Adding integers with different signs: find the difference of their absolute values, keep the sign of the larger absolute value (e.g. -7 + 3 = -4, since 7>3 and the 7 was negative). (Research: this rule is distinct from integer multiplication/division rules — Lesson 112 has entirely different rules. Explicit side-by-side contrast of \"addition rule vs. multiplication rule\" prevents the rule confusion that otherwise persists into algebra.)", watchFor: "Students default to just adding the numbers and guessing the sign — the reliable rule is \"same signs, add and keep the sign; different signs, subtract and keep the sign of the bigger number.\" Contrast this rule explicitly with the multiplication rule coming in Lesson 112 (same signs give positive, different signs give negative) so they're not treated as variations of the same rule. (R5 technique: establish the ONE focus — 'we're nailing addition with different signs' — and defer the multiplication rule to Lesson 112. Avoid comprehensive rule-dump; narrow to addition only.)", differentiation: { tier1: "Use a number line with physical movement: -7 + 3 = 'start at -7, move right 3.' Do 5–6 examples with the class saying the rule aloud: 'Different signs: subtract, keep the bigger sign.' Always contrast same-sign addition (e.g., -7 + -3 = -10) right after.", tier2: "Small-group: provide a card with the rule and a worked example (-7 + 3 = -4, with 'difference = 4, bigger sign is negative'). Give students 10 problems with the card visible; gradually remove the card. Use consistent language: 'Find the difference, keep the bigger sign.'", tier3: "Diagnostic: ask '-7 + 3 = ?' If they add (7 + 3 = 10) without finding the difference, teach the 'difference first' process: write '|−7| = 7' and '|3| = 3,' then '7 − 3 = 4,' then 'bigger number is negative, so -4.' Daily drills on mixed-sign addition with explicit 'difference → sign' steps; spaced 2–3 times per week." } },
  { key: "Investigation 10", title: "Compound Experiments", concept: "The probability of two independent events BOTH happening is the product of their individual probabilities (e.g. two coin flips both heads = 1/2 × 1/2 = 1/4) — a tree diagram or table makes all outcomes visible.", watchFor: "Students add probabilities instead of multiplying them for \"and\" (both happening) scenarios — multiplication is for \"and,\" addition is for \"or\" (mutually exclusive events)." },
  { key: "106", title: "Two-Step Equations", concept: "Solving requires undoing operations in reverse order of how they were applied — e.g. for 3x + 5 = 20, subtract 5 first, THEN divide by 3 (undo addition before undoing multiplication). (Research: worked-example effect is strong for algebra: showing a fully-solved 3x + 5 = 20 on the board, stepping through each undo, beats giving hints or having students discover the order on their own. Effect size d≈0.48 for novices. The reason: equations are cognitively load-heavy (tracking multiple operations, maintaining balance), so seeing the full path once frees cognitive resources to understand the strategy.)", watchFor: "Students try to divide by 3 first, before isolating the term with the variable — reinforce \"undo in reverse PEMDAS order\" as the general strategy for any multi-step equation. (R5 Jim Knight Impact Cycle 'Learn' stage: always show TWO fully-worked examples (different numbers) BEFORE assigning practice; the worked-example effect is largest for algebra when the model is visible before the release to practice. Point to each step aloud: this explicit modeling frees cognitive load.)", differentiation: { tier1: "Show a fully-worked example on the board: 3x + 5 = 20. Step through each line: 'Subtract 5 from both sides' → 3x = 15. 'Divide both sides by 3' → x = 5. Point to the order: 'Undo in reverse: last operation added was +5, so subtract first. Then undo the multiplication by 3.' Show a second fully-worked example (different numbers) immediately after. Model before assigning practice.", tier2: "Small-group: give students 3–4 two-step equations with the answer already worked out on the card. Have them read the worked steps aloud, then solve a similar problem without the card. Use the phrase 'undo in reverse' consistently. Start with straightforward integers before mixing in fractions/negatives.", tier3: "Diagnostic: ask them to solve 3x + 5 = 20. Watch for the order: if they divide by 3 first (wrong), stop and ask 'What's the LAST operation in 3x + 5?' (addition). 'So we undo that first.' Then solve together, pointing to each step. Daily equation-solving drills (3–5 equations) with explicit 'undo in reverse' narration; check the order before checking the arithmetic." } },
  { key: "108", title: "Transformations", concept: "Translations (slide), reflections (flip), and rotations (turn) all preserve a shape's size and form — only its position/orientation changes. Dilation (a scale-factor resize) is the one transformation that DOES change size.", watchFor: "Students conflate reflection and rotation (both can look similar for simple shapes) — always ask \"did it flip across a line, or spin around a point?\"", differentiation: { tier1: "Draw a triangle on the board and label it △ABC. Model each transformation: (1) TRANSLATION (slide): move it right 3 units. Say: 'The shape didn't flip or turn, just slid.' (2) REFLECTION (flip): draw a line of reflection, flip the triangle across it. Say: 'It flipped like a mirror image across this line.' (3) ROTATION (turn): draw a point, rotate the triangle around it 90°. Say: 'It spun around a center point.' (4) DILATION: resize it larger by scale factor 2. Say: 'This one CHANGED size.' Do each one with different triangles so students see the distinction clearly.", tier2: "Small-group: provide several triangles with transformations already done. For each, students identify: translation, reflection, rotation, or dilation? Use the cues: 'Did it flip? (reflection) Did it spin? (rotation) Did it slide? (translation) Did it resize? (dilation)' Daily practice on 6–8 examples of each type.", tier3: "Diagnostic: show a reflection and a rotation side-by-side that look similar. Ask 'Which is which?' Teach the distinction: 'Did it flip across a line? (reflection) Or spin around a point? (rotation)' Use physical demonstrations: fold paper for reflection, spin a shape for rotation. Daily practice on mixed transformations, emphasizing the line-of-reflection vs. center-of-rotation distinction." } },
  { key: "109", title: "Corresponding Parts, Similar Triangles", concept: "Similar triangles have the same shape (equal corresponding angles) but not necessarily the same size — corresponding sides are all in the same ratio (the scale factor).", watchFor: "Students match up sides/angles in the wrong order between two similar triangles — always match corresponding parts by their position in the similarity statement (e.g. △ABC ~ △DEF means A↔D, B↔E, C↔F, not by eyeballing which sides \"look similar\").", differentiation: { tier1: "Draw two similar triangles on the board, label the first △ABC (small) and the second △DEF (larger). Write: △ABC ~ △DEF. Say: 'The order matters. A corresponds to D, B to E, C to F. Side AB corresponds to side DE, and the ratio of sides is the same: AB/DE = BC/EF = AC/DF.' Write the sides: if AB=3, BC=4, AC=5, and DE=6, then BC/EF = 4/8, so EF=8. Do this step-by-step, matching by position in the similarity statement, not by appearance.", tier2: "Small-group: provide pairs of similar triangles with one labeled (△ABC) and the other unlabeled. Have students identify which vertex of the second triangle corresponds to A, B, C (using angle measures or side ratios). Write the similarity statement: △ABC ~ △???. Then use the correspondence to find missing sides.", tier3: "Diagnostic: show △ABC ~ △DEF with some side lengths missing. Ask 'What side in △DEF corresponds to AB?' If they guess by appearance instead of position, correct: 'The statement says A↔D, B↔E, so AB ↔ DE. That's the corresponding side.' Use the order to match parts. Daily practice on 3–4 similar-triangle pairs, emphasizing correspondence by position in the statement." } },
  { key: "112", title: "Multiplying and Dividing Integers", concept: "Same-sign integers multiply/divide to a positive result; different-sign integers give a negative result — this is a fixed rule, not something that varies by the specific numbers involved. (Research: teaching this rule in isolation leaves students unable to distinguish it from the addition rule. Best practice: teach multiplication rule by explicitly contrasting it to addition rule on the same day or the next day, side-by-side, showing all four sign combinations for both operations so the difference is concrete.)", watchFor: "Students apply the addition/subtraction sign rules (Lesson 100) to multiplication/division by mistake — these are genuinely different rule sets and worth explicitly contrasting side by side. (R5 technique: establish the ONE focus — 'today we lock down the multiplication/division sign rule' — then immediately contrast to addition the next day or in the next hour, side-by-side. Don't try to teach both rules in one sitting; narrow the focus and then iterate with comparison.)", differentiation: { tier1: "Create a side-by-side chart on the board: | ADDING | MULTIPLYING |. Fill in: ADDING: -7 + 3 = -4 (different signs: find difference, keep bigger sign). MULTIPLYING: -7 × 3 = -21 (different signs: always negative). Say aloud: 'The RULES are different. Addition finds a difference. Multiplication doesn't.' Model all four combinations (-×-, -×+, +×-, +×+) for multiplication while contrasting to addition. Use the same language every time: 'Same signs give POSITIVE. Different signs give NEGATIVE.'", tier2: "Small-group: provide a rule card (chart above) and give them 10 mixed addition and multiplication problems. Have them label each one 'ADDITION' or 'MULTIPLICATION' before solving. Use consistent numbers (-7, 3) across problems so they can practice saying the rule both ways. Start with same-sign problems (easier), then add mixed-sign.", tier3: "Diagnostic: mix addition and multiplication: 'Is -7 + 3 = -4 or -21?' (addition, -4). 'Is -7 × 3 = -4 or -21?' (multiplication, -21). If they confuse them, create a mnemonicseparation: 'ADDING with different signs: difference. MULTIPLYING with different signs: always negative, never a difference.' Daily drills (5–10 mixed problems, labeled by type); daily contrast on the same numbers (-7, 3) for both operations. Spaced 3 times per week." } },
  { key: "114", title: "Unit Multipliers", concept: "A unit multiplier is a fraction equal to 1 (like 12 in/1 ft) used to convert units by multiplying — since it equals 1, multiplying by it changes the units without changing the actual quantity.", watchFor: "Students set up the unit multiplier upside down (canceling the wrong unit) — the unit you want to CANCEL should be in the position (top or bottom) opposite where it appears in the original quantity." },
  { key: "116", title: "Compound Interest", concept: "Compound interest earns interest on both the original principal AND on previously earned interest — unlike simple interest, the amount grows faster over time because each period's interest is calculated on a larger base.", watchFor: "A genuinely good moment for a real personal-finance tie-in (savings accounts, loans) — students retain this concept far better with a real dollar example than with the formula alone." },
  { key: "120", title: "Volume of a Cylinder", concept: "Volume = πr²h — literally \"circle area (πr²) × height,\" the same base-times-height logic as a rectangular prism, just with a circular base.", watchFor: "Students forget to square the radius (using πrh instead of πr²h) — tie it back explicitly to the circle-area formula from Lesson 86 so it's recognized as the same base area, not a brand-new formula." },
  { key: "Investigation 12", title: "Platonic Solids", concept: "There are exactly five: tetrahedron, cube, octahedron, dodecahedron, icosahedron — each made of one type of regular polygon, with the same number of faces meeting at every vertex. A nice closing-of-the-year fact: geometers proved 2,000+ years ago that exactly five (no more, no fewer) can exist.", watchFor: "A good place to let curiosity lead rather than drilling facts — the \"why only five\" proof (based on angle sums around a vertex) is genuinely elegant and worth mentioning even if not required material." },
];

// Lesson numbers match as a whole word (so "11" doesn't false-match inside "111");
// investigations match their exact phrase.
export function getSaxonNotesForWeekText(weekText: string): SaxonTeacherNote[] {
  const found: SaxonTeacherNote[] = [];
  for (const note of saxonTeacherGuide) {
    if (note.key.startsWith("Investigation")) {
      if (weekText.includes(note.key)) found.push(note);
    } else {
      const re = new RegExp(`\\b${note.key}\\b`);
      if (re.test(weekText)) found.push(note);
    }
  }
  return found;
}
